   "titulo": "Exclusivo: Documentos prueban el papel clave de Rivero Lazo en la creación del Grupo Colina",
   "resumen": "",
   "fuente": "Convoca",
   "url": "https://news.google.com/rss/articles/CBMitwFBVV95cUxPOXJSaWk1TTJ1ZHdpWTh5SWJyYTBTb2FrcVFNQlhqaUFVLWJodzBRaUJLejRFdjJjdWFZM0x6QUFkNWlQZHNULVV2YTBiVkljaGdfSG44a1cwdHJuZFF0d3ZKZThtZEdiTjJ0UzJ2RVhoSGI1ZDNvb3FBTWxoOFE2dXlRS0dsTDV3aGdZMjFWTzhIUjMwWjUzVjRKaFNsVk1ocDBrbVZHOWttRzlOeWVlR2VYUnZqWmM?oc=5",
   "fecha": "2026-11-17T08:00:00Z",
   "tipo": "independiente",
   "genero": "noticia",
   "imagen": "https://convoca.pe/sites/default/files/2026-11/Rospi%20y%20Rivero%20lazo%20con%20documento%20mejorado.png",
   "geografia": {
    "version": 1,
    "ambito": "pendiente",
    "zona": "pendiente",
    "motivo": "sin_evidencia_geografica"
   },
   "ambito": "pendiente",
   "procedencia": "agregador",
   "via": "Google Noticias",
   "url_medio": "https://convoca.pe/agenda-propia/exclusivo-documentos-revelan-el-papel-clave-de-rivero-lazo-en-la-creacion-del-grupo",
   "sintesis": "El 30 de noviembre empieza el nuevo juicio oral contra miembros del Ejército por el asesinato del líder sindical Pedro Huilca Tecse, y uno de los procesados es el general (r) Juan Rivero Lazo, condenado como autor mediato por los crímenes de Destacamento Colina, en su calidad de jefe de la Dirección de Inteligencia del Ejército. El senador fujimorista Fernando Rospigliosi ha señalado que existe una persecución contra el oficial, sin embargo, documentos militares con su firman demuestran que su papel en la creación del grupo que ejecutó medio centenar de personas entre 1991 y 1992.",
